local config = {
  ui_story_5010_50100101_1_dialog_content = "\"As living beings, we should show love, compassion, and respect to all lives.\"",
  ui_story_5010_50100101_2_dialog_content = "\"As such, we did what we thought was right, and it is not necessary to thank us.\"",
  ui_story_5010_50100101_3_dialog_content = "\"Be well, young PlayerName.\"",
  ui_story_5010_50100101_4_dialog_content = "Wow... The letter from the <color=#FFB400>Lin Guild</color> really shows that they're a very civilized family!",
  ui_story_5010_50100101_5_dialog_content = "I should try writing Vice a letter using the same style someday...",
  ui_story_5010_50100101_6_dialog_content = "\"Dear Vice, how have you fared as of late? Have you grown accustomed to your training regimen in Illumina?\"",
  ui_story_5010_50100101_7_dialog_content = "\"Regardless, as comrades, learning the subtle art of cooking is of the utmost importance...\"",
  ui_story_5010_50100101_8_dialog_content = "\"Chubby bird! Chubby!\"",
  ui_story_5010_50100101_9_dialog_content = "Hey! Rude!",
  ui_story_5010_50100101_10_dialog_content = "Huh?",
  ui_story_5010_50100101_11_dialog_content = "Yaaas!",
  ui_story_5010_50100101_12_dialog_content = "Wanna hear my joke first?",
  ui_story_5010_50100101_13_dialog_content = "It's super-duper-extra funny! Yoshi lost two pounds just from laughing after hearing it!",
  ui_story_5010_50100101_14_dialog_content = "Some other time, maybe... Hey, you have a letter hanging out of your bag there.",
  ui_story_5010_50100101_15_dialog_content = "Looks like it's addressed to... me? Here, let me see it.",
  ui_story_5010_50100101_16_dialog_content = "You don't even have time for a little joke? Fine!",
  ui_story_5010_50100101_17_dialog_content = "Here's your letter!",
  ui_story_5010_50100101_18_dialog_content = "From the <color=#FFB400>Shadowlord</color> himself!",
  ui_story_5010_50100101_19_dialog_content = "They specifically requested that I watch you read the whole thing.",
  ui_story_5010_50100101_20_dialog_content = "So hurry it up! I haven't got all day!",
  ui_story_5010_50100101_21_dialog_content = "O-Okay! I wonder what it could be? Must be pretty important...",
  ui_story_5010_50100101_22_dialog_content = "Dear PlayerName,",
  ui_story_5010_50100101_24_dialog_content = "\"Based on your various deeds...\"",
  ui_story_5010_50100101_25_dialog_content = "\"Both the Illumina Federation and Lumopolis acknowledge you as the sole representative of the Caelestites. Naturally, Umbraton is no exception...\"",
  ui_story_5010_50100101_26_dialog_content = "C'mon, already! I have other letters to deliver, you know!",
  ui_story_5010_50100101_27_dialog_content = "\"As the representative of Umbraton, I now declare that all Caelestite assets deposited in Umbraton are the exclusive property of yours, the last of the Caelestites...\"",
  ui_story_5010_50100101_28_dialog_content = "\"You may use this letter as proof of your right to claim ownership, and the Umbraton Guild Headquarters will handle all logistical procedures...\"",
  ui_story_5010_50100101_29_dialog_content = "\"The location of the headquarters is... The person in charge of this matter is... Their terminal contact information is as follows...\"",
  ui_story_5010_50100101_30_dialog_content = "\"... And <color=#FFB400>Bethel</color> will be responsible for escorting you to the Guild's bank, as well as arranging all inheritance paperwork...\"",
  ui_story_5010_50100101_31_dialog_content = "Seventeen Fireflies... eighteen Fireflies...",
  ui_story_5010_50100101_32_dialog_content = "\"Yours faithfully, Istvan.\"",
  ui_story_5010_50100101_33_dialog_content = "Caelestite assets...?",
  ui_story_5010_50100101_34_dialog_content = "Uh... Eho? What kind of assets did the Caelestites have in Umbraton?",
  ui_story_5010_50100101_35_dialog_content = "No idea.",
  ui_story_5010_50100101_36_dialog_content = "Then do you know how long it takes the Guild to handle all the paperwork?",
  ui_story_5010_50100101_37_dialog_content = "Not a clue!",
  ui_story_5010_50100101_38_dialog_content = "Then... Do you at least know who this <color=#FFB400>Bethel</color> person is?",
  ui_story_5010_50100101_39_dialog_content = "Ah-hah! I know this one!",
  ui_story_5010_50100101_40_dialog_content = "She's in charge of the Guild headquarters, and she is the Shadowlord's adopted daughter!",
  ui_story_5010_50100101_41_dialog_content = "I heard that she came back to Umbraton after studying in Lumopolis, and she has some cute puppies with her!",
  ui_story_5010_50100101_42_dialog_content = "Adopted daughter? Just how many adopted daughters does the Shadowlord have...?",
  ui_story_5010_50100101_43_dialog_content = "Meh, that's not important!",
  ui_story_5010_50100101_44_dialog_content = "Oh, yeah! Lady <color=#FFB400>Naroxel</color> also asked me to pass on a message to you!",
  ui_story_5010_50100101_45_dialog_content = "Why doesn't she just tell me herself...?",
  ui_story_5010_50100101_46_dialog_content = "She's very busy, you know! Now listen up...",
  ui_story_5010_50100101_47_dialog_content = "\"Greetings, PlayerName.\"",
  ui_story_5010_50100101_48_dialog_content = "\"It has come to my attention that a certain set of <color=#FFB400>simulation room components</color> will soon be listed in an underground auction in Umbraton.\"",
  ui_story_5010_50100101_49_dialog_content = "\"From my own understanding, components such as these were often used to modify or even upgrade Colossi.\"",
  ui_story_5010_50100101_50_dialog_content = "\"If you are interested, it may behoove you to see them for yourself. Perhaps they can be of use to Soroz in the future?\"",
  ui_story_5010_50100101_51_dialog_content = "\"May nature always protect you... Your friend, Naroxel.\"",
  ui_story_5010_50100101_52_dialog_content = "\"<color=#FFB400>Simulation room components</color>\"? ... Hey, Eho?",
  ui_story_5010_50100101_53_dialog_content = "Caw? What now?",
  ui_story_5010_50100101_54_dialog_content = "Do you know what the underground auction is about?",
  ui_story_5010_50100101_55_dialog_content = "Well, of course I do! It's an auction, obviously... And it happens to be underground!",
  ui_story_5010_50100101_56_dialog_content = "You'd know if you go and see for yourself, right? Ah, you are so very slow.",
  ui_story_5010_50100101_57_dialog_content = "I'm leaving for real, now! I still have eighteen other deliveries to make today!",
  ui_story_5010_50100101_58_dialog_content = "Okay, thanks for... Oh, she's already gone. It must be nice to have wings like that...",
  ui_story_5010_50100101_59_dialog_content = "Hmm... lots to think about now. I need some time...",
  ui_story_5010_50100101_60_dialog_content = "The Guild headquarters, the underground auction...",
  ui_story_5010_50100101_61_dialog_content = "Oh! I can also stop by the Lin Guild and say hello!",
  ui_story_5010_50100101_62_dialog_content = "\"Please contact the following number via the terminal, and the head of the Guild will meet you outside Umbraton...\"",
  ui_story_5010_50100101_63_dialog_content = "Looks like our next stop is <color=#FFB400>Umbraton</color>!",
  ui_story_5010_50100201_1_dialog_content = "Hello? Is this PlayerName? This is Bethel, from the Umbraton Guild.",
  ui_story_5010_50100201_2_dialog_content = "H-Hello!",
  ui_story_5010_50100201_3_dialog_content = "Please land to the east of the <color=#FFB400>Dam of Scars</color>. I will await you there.",
  ui_story_5010_50100201_4_dialog_content = "Not a problem!",
  ui_story_5010_50100201_5_dialog_content = "Umbraton looks really impressive from this angle.",
  ui_story_5010_50100201_6_dialog_content = "Umbraton... A city known as the Shadow of Lumopolis.",
  ui_story_5010_50100201_7_dialog_content = "<color=#e8d9bb>We will soon be arriving at our destination. Please confirm your landing zone prior to arrival.</color>",
  ui_story_5010_50100201_8_dialog_content = "Oh, no... I totally forgot to ask where the Dam of Scars is.",
  ui_story_5010_50100201_9_dialog_content = "Guess I'll go look for it myself...",
  ui_story_5010_50100201_10_dialog_content = "Hello again. You must be PlayerName. I'm Bethel.",
  ui_story_5010_50100201_11_dialog_content = "Yes! H-Hi...",
  ui_story_5010_50100201_12_dialog_content = "And this must be the Colossus... It is as magnificent as the stories say. I imagine it must be quite difficult to pilot?",
  ui_story_5010_50100201_13_dialog_content = "It seems you had some difficulty landing it.",
  ui_story_5010_50100201_14_dialog_content = "N-Not really, I just got a little lost. I don't come to Umbraton very often, you see...",
  ui_story_5010_50100201_15_dialog_content = "To be quite honest, I nearly got lost on my way here, as well.",
  ui_story_5010_50100201_16_dialog_content = "Umbraton has surely changed a lot in recent years...",
  ui_story_5010_50100201_17_dialog_content = "But enough about that. Please, right this way.",
  ui_story_5010_50100201_18_dialog_content = "(If I knew she was going to be so formal, I would've dressed up a little...)",
  ui_story_5010_50100201_19_dialog_content = "Then... are we going to the headquarters now?",
  ui_story_5010_50100201_20_dialog_content = "Also... Could you tell me what these Caelestite assets are, exactly?",
  ui_story_5010_50100201_21_dialog_content = "The ledger describes them as a number of chests. Only the owner is authorized to open them and ascertain their contents.",
  ui_story_5010_50100201_22_dialog_content = "Umbraton's Guild Headquarters... Pardon me, but do you manage all of the Guild's operations? Are underground auctions also under your jurisdiction?",
  ui_story_5010_50100201_23_dialog_content = "Underground auctions?",
  ui_story_5010_50100201_24_dialog_content = "Although I have no idea where you came across this term, I'm afraid I have very little information to divulge on the matter.",
  ui_story_5010_50100201_25_dialog_content = "Could it be that you wish to auction off the Caelestite assets you have come to claim?",
  ui_story_5010_50100201_26_dialog_content = "Ah! I-I didn't mean it like that! I just heard that someone was putting some Caelestite stuff up for auction... So I thought I'd ask you about it.",
  ui_story_5010_50100201_27_dialog_content = "That would be far beneath us. The Umbraton Guild would never engage in the unauthorized sale of other people's properties.",
  ui_story_5010_50100201_28_dialog_content = "R-Right.",
  ui_story_5010_50100201_29_dialog_content = "Please keep up, if you would.",
  ui_story_5010_50100201_30_dialog_content = "...",
  ui_story_5010_50100201_31_dialog_content = "(I feel like I need to say something here... But what should I talk about?)",
  ui_story_5010_50100201_32_option_content = "Ask about the Lin Guild",
  ui_story_5010_50100201_33_dialog_content = "Um, Bethel...? Are you familiar with the <color=#FFB400>Lin Guild</color>?",
  ui_story_5010_50100201_34_dialog_content = "Of course.",
  ui_story_5010_50100201_35_option_content = "Ask about the dam",
  ui_story_5010_50100201_36_dialog_content = "That dam we passed on the way here was huge! Did the people of Umbraton build it themselves?",
  ui_story_5010_50100201_37_dialog_content = "It was constructed at the behest of the Shadowlord to circumvent any hazardous weather anomalies.",
  ui_story_5010_50100201_38_dialog_content = "Under his guidance, each of the major guilds invested in the project, the largest benefactor being the <color=#FFB400>Lin Family</color>.",
  ui_story_5010_50100201_39_dialog_content = "Then... The Lin Guild...",
  ui_story_5010_50100201_40_dialog_content = "Yes? Are you interested in them?",
  ui_story_5010_50100201_41_dialog_content = "I've only heard a few things here and there about them. After all, they've always been pretty... elusive.",
  ui_story_5010_50100201_42_dialog_content = "They specialize in handmade products. Their porcelain is of the highest quality, as are their folding fans.",
  ui_story_5010_50100201_43_dialog_content = "Are you perhaps interested in conducting business with the Lin Family?",
  ui_story_5010_50100201_44_dialog_content = "N-No, that's not it... They helped me out with something really important in the past, so I wanted to stop by and say hello.",
  ui_story_5010_50100201_45_dialog_content = "I see. The Lin Guild Hall is on the way to our headquarters...",
  ui_story_5010_50100201_46_dialog_content = "Great! Oh, right... What kind of paperwork needs to be taken care of at the headquarters?",
  ui_story_5010_50100201_47_dialog_content = "It's quite simple, really. You will be given all the time in the world to look over every ledger and asset as well. Please put your mind at ease.",
  ui_story_5010_50100201_48_dialog_content = "Okay. I just hope it's not too far away...",
  ui_story_5010_50100201_49_dialog_content = "We will be there shortly, I assure you...",
  ui_story_5010_50100201_50_dialog_content = "Wait. Frankel senses that something is amiss.",
  ui_story_5010_50100201_51_dialog_content = "Frankel?",
  ui_story_5010_50100201_52_dialog_content = "My familiar.",
  ui_story_5010_50100201_53_dialog_content = "They seem to have picked up a foul scent... A familiar one.",
  ui_story_5010_50100201_54_dialog_content = "I can sense them, too... Eclipsites!!",
  ui_story_5010_50100201_55_dialog_content = "Woof! Woof!",
  ui_story_5010_50100201_56_dialog_content = "Watch out, Bethel!",
  ui_story_5010_50100201_57_dialog_content = "I can sense them... The Eclipsites are closing in on our position, and fast!",
  ui_story_5010_50100201_58_dialog_content = "You can perceive their movements so clearly? This must be the power of the Caelestites!",
  ui_story_5010_50100201_59_dialog_content = "Rest assured...",
  ui_story_5010_50100201_60_dialog_content = "I will eradicate every single one of them.",
  ui_story_5010_50100202_1_dialog_content = "It didn't feel like they were just roaming around. Rather...",
  ui_story_5010_50100202_2_dialog_content = "It was almost if they were going straight for their target.",
  ui_story_5010_50100202_3_dialog_content = "By target, I mean it's you, isn't it, PlayerName?",
  ui_story_5010_50100202_4_dialog_content = "I...",
  ui_story_5010_50100202_5_dialog_content = "Wait... There's more of them!",
  ui_story_5010_50100202_6_dialog_content = "Graaaaaagh!!",
  ui_story_5010_50100202_7_dialog_content = "I'll take the ones in the front! Stay behind me for now!",
  ui_story_5010_50100202_8_dialog_content = "Heads up!",
  ui_story_5010_50100202_9_dialog_content = "Graa—",
  ui_story_5010_50100202_10_dialog_content = "What's this? You're still standing after all of that? You're a little different from the rumors say, Caelestite.",
  ui_story_5010_50100202_11_dialog_content = "... H-Have you been following us this whole time?",
  ui_story_5010_50100202_12_dialog_content = "A member of the <color=#FFB400>White Flame Mercenaries</color>? So... You even hired a bodyguard.",
  ui_story_5010_50100202_13_dialog_content = "To hide you presence so well all this time... I'm thankful that you aren't our enemy.",
  ui_story_5010_50100202_14_dialog_content = "I'm <color=#FFB400>Luke</color>, of the White Flame Mercenaries. I received a request from Naroxel to protect you, PlayerName.",
  ui_story_5010_50100202_15_dialog_content = "Protect me?",
  ui_story_5010_50100202_16_dialog_content = "That's right! Naroxel says you're a good friend of hers, and that you helped her out in the past.",
  ui_story_5010_50100202_17_dialog_content = "... PlayerName, I have also requested that Luke, an old friend of mine, come to your aid...",
  ui_story_5010_50100202_18_dialog_content = "But Umbraton isn't a war zone! Why would I need protection?",
  ui_story_5010_50100202_19_dialog_content = "Hey, I'm just a mercenary. I never ask any questions.",
  ui_story_5010_50100202_20_dialog_content = "Ahem...",
  ui_story_5010_50100202_21_dialog_content = "Ah! Good day, Lady Bethel of the Guild. Such combat prowess is to be expected of Lord Istvan's successor, after all!",
  ui_story_5010_50100202_22_dialog_content = "Hmph...",
  ui_story_5010_50100202_23_dialog_content = "Hold on... Luke. Do you know anything about underground auctions?",
  ui_story_5010_50100202_24_dialog_content = "Not a lot, but I could always gather some information for you, if you'd like?",
  ui_story_5010_50100202_25_dialog_content = "Really? That'd be great! See, I want to go to the auction to find out if...",
  ui_story_5010_50100202_26_dialog_content = "PlayerName, I believe we should first return to headquarters to attend to our first order of business!",
  ui_story_5010_50100202_27_dialog_content = "Will you continue escorting us from the rear, Luke? I believe there is no reason to keep yourself hidden now.",
  ui_story_5010_50100202_28_dialog_content = "Heh, sorry. Just an old habit in my line of work...",
  ui_story_5010_50100202_29_dialog_content = "We knocked the airship out of the sky!",
  ui_story_5010_50100202_30_dialog_content = "Good! Continue the search! Make sure the dead are dead and bring the rest to me!",
  ui_story_5010_50100202_31_dialog_content = "Rhein...",
  ui_story_5010_50100202_32_dialog_content = "Hmm?",
  ui_story_5010_50100202_33_dialog_content = "How are things going?",
  ui_story_5010_50100202_34_dialog_content = "All according to the plan.",
  ui_story_5010_50100301_1_dialog_content = "Wow, the buildings in Umbraton are very distinctive!",
  ui_story_5010_50100301_2_dialog_content = "But somehow it feels so much stuffier in the city.",
  ui_story_5010_50100301_3_dialog_content = "How annoying... They said it was going to rain, but we haven't gotten so much as a drop all this time.",
  ui_story_5010_50100301_4_dialog_content = "Ah...!",
  ui_story_5010_50100301_5_dialog_content = "Look, look! A new tournament is about to begin!",
  ui_story_5010_50100301_6_dialog_content = "Huh? A flyer...?",
  ui_story_5010_50100301_7_dialog_content = "Let me see... Ah, it's for the Underground Arena.",
  ui_story_5010_50100301_8_dialog_content = "Underground Arena...?",
  ui_story_5010_50100301_9_dialog_content = "They're private matches, so they're considered underground. Kind of like that auction you mentioned earlier.",
  ui_story_5010_50100301_10_dialog_content = "The rules for these unspeakable fights are simple. Beat your opponent using any means necessary, and you win.",
  ui_story_5010_50100301_11_dialog_content = "And if you happen to kill your opponent... You're not liable for anything.",
  ui_story_5010_50100301_12_dialog_content = "Wow... But it sounds so brutal. How...",
  ui_story_5010_50100301_13_dialog_content = "Well, it's true that these fights are completely illegal... But this is still Umbraton.",
  ui_story_5010_50100301_14_dialog_content = "So... everyone is willing to risk their lives for the rewards?",
  ui_story_5010_50100301_15_dialog_content = "Not exactly, no. For real fighters, these underground matches are the perfect training grounds...",
  ui_story_5010_50100301_16_dialog_content = "That building is the Lin Guild Hall, PlayerName.",
  ui_story_5010_50100301_17_dialog_content = "Is this one of their shops? It looks special, that's for sure.",
  ui_story_5010_50100301_18_dialog_content = "Indeed. Much like their products, it is a testament to their exquisite craftsmanship.",
  ui_story_5010_50100301_19_dialog_content = "There's only a guard posted at the entrance, as well as a notice that says the shop is closed today.",
  ui_story_5010_50100301_20_dialog_content = "Ah... what a shame... Looks like I'll have to wait until next time to see them.",
  ui_story_5010_50100301_21_dialog_content = "Now then, if there is nothing else, please follow me to our headquarters, PlayerName.",
  ui_story_5010_50100301_22_dialog_content = "... Okay.",
  ui_story_5010_50100301_23_dialog_content = "Ah... It seems the Truth has led me to you today, Luke.",
  ui_story_5010_50100301_24_dialog_content = "Oh, you... I take it everything went smoothly, then?",
  ui_story_5010_50100301_25_dialog_content = "Naturally...",
  ui_story_5010_50100301_26_dialog_content = "W-Wait, you two know each other?",
  ui_story_5010_50100301_27_dialog_content = "Long time no see, PlayerName. I would say that our meeting is a blessing of the Truth...",
  ui_story_5010_50100301_28_dialog_content = "But Umbraton has never been such a simple place. I pray that you will be alert to the surrounding perils... Both seen and unseen.",
  ui_story_5010_50100301_29_dialog_content = "Would you stop speaking in riddles? How could I be alert to things I can't see in the first place?",
  ui_story_5010_50100301_30_dialog_content = "Don't worry about it. You have me at your side, as well as Bethel.",
  ui_story_5010_50100301_31_dialog_content = "Indeed. I guarantee that you will be perfectly safe in Umbraton under my watch, PlayerName.",
  ui_story_5010_50100301_32_dialog_content = "Ah yes, hearing this puts my mind at ease.",
  ui_story_5010_50100301_33_dialog_content = "Until we meet next time, PlayerName.",
  ui_story_5010_50100301_34_dialog_content = "What did Faust give you, Luke?",
  ui_story_5010_50100301_35_dialog_content = "Hmm... A surprise, you could say. You'll find out soon enough.",
  ui_story_5010_50100301_36_dialog_content = "... I hope you two are having fun with this.",
  ui_story_5010_50100301_37_dialog_content = "We have finally arrived. Welcome to the Umbraton Guild Headquarters.",
  ui_story_5010_50100301_38_dialog_content = "This looks nothing like a guild... It looks like a fortress! No wonder Luke says people avoid making trouble around here...",
  ui_story_5010_50100301_39_dialog_content = "Lady Bethel.",
  ui_story_5010_50100301_40_dialog_content = "Good day. Any word from the Shadowlord?",
  ui_story_5010_50100301_41_dialog_content = "Not yet, my lady.",
  ui_story_5010_50100301_42_dialog_content = "I'll go bring the necessary materials. Please wait a moment.",
  ui_story_5010_50100301_43_dialog_content = "As you wish, my lady. This way, please.",
  ui_story_5010_50100301_44_dialog_content = "(E-Everyone's so courteous around here! How should I react?)",
  ui_story_5010_50100301_45_dialog_content = "... You don't need to bow, PlayerName.",
  ui_story_5010_50100301_46_dialog_content = "This place makes me nervous.",
  ui_story_5010_50100301_47_dialog_content = "I'll just wait for you outside.",
  ui_story_5010_50100301_48_dialog_content = "My apologies for the wait, PlayerName. Here is the asset ledger, as well as the relevant documentation. Please read over them for as long as you wish.",
  ui_story_5010_50100301_49_dialog_content = "Where has Luke gone?",
  ui_story_5010_50100301_50_dialog_content = "He just stepped outside a few seconds ago... Whoa! This is a lot of paperwork!",
  ui_story_5010_50100301_51_dialog_content = "My apologies. The process is somewhat complicated. I will do my best to simplify it, but certain places will still require your signature.",
  ui_story_5010_50100301_52_dialog_content = "Here, for example. And here. And here...",
  ui_story_5010_50100301_53_dialog_content = "Do you need me to explain any of this?",
  ui_story_5010_50100301_54_dialog_content = "G-Graaah...!",
  ui_story_5010_50100301_55_dialog_content = "Ahh! H-H-He just turned into an...",
  ui_story_5010_50100301_56_dialog_content = "PlayerName! There's an Eclipsite at the main entrance!",
  ui_story_5010_50100301_57_dialog_content = "?!",
  ui_story_5010_50100301_58_dialog_content = "How did an Eclipsite suddenly appear here?!",
  ui_story_5010_50100301_59_dialog_content = "Evacuating the civilians is our top priority! Shut the main gate, and escort everyone out from the back!",
  ui_story_5010_50100301_60_dialog_content = "Understood!",
  ui_story_5010_50100301_61_dialog_content = "You have some nerve... Stirring up trouble in front of the Guild!",
  ui_story_5010_50100301_62_dialog_content = "There's more!",
  ui_story_5010_50100301_63_dialog_content = "Fight, Frankel!",
  ui_story_5010_50100301_64_dialog_content = "Get behind me, PlayerName!",
  ui_story_5010_50100401_1_dialog_content = "Lady Bethel!",
  ui_story_5010_50100401_2_dialog_content = "Are you... Oh, thank goodness you're alright, my lady!",
  ui_story_5010_50100401_3_dialog_content = "Where are the guards? Why are there so few people here?",
  ui_story_5010_50100401_4_dialog_content = "D-Don't worry, Lady Bethel! I'll find more help! Leave this to me!",
  ui_story_5010_50100401_5_dialog_content = "Was that your men, Bethel?",
  ui_story_5010_50100401_6_dialog_content = "Yes, what of it?",
  ui_story_5010_50100401_7_dialog_content = "These people don't seem to have any combat experience. Just look at them, they're all scared to death.",
  ui_story_5010_50100401_8_dialog_content = "Hmph...",
  ui_story_5010_50100401_9_dialog_content = "Wait!",
  ui_story_5010_50100401_10_dialog_content = "Have you discovered something?",
  ui_story_5010_50100401_11_dialog_content = "That corner! Something's there!",
  ui_story_5010_50100401_12_dialog_content = "... Frankel, go see what's up ahead.",
  ui_story_5010_50100401_13_dialog_content = "Woof!",
  ui_story_5010_50100401_14_dialog_content = "Graagh!",
  ui_story_5010_50100401_15_dialog_content = "Woof! Woof!",
  ui_story_5010_50100401_16_dialog_content = "That was swift, isn't it?",
  ui_story_5010_50100401_17_dialog_content = "Graaaaaah!!",
  ui_story_5010_50100401_18_dialog_content = "Simple-minded, all the same. Sending Frankel ahead was all it took to draw it out.",
  ui_story_5010_50100401_19_dialog_content = "Thank you for the warning, PlayerName. You're very perceptive.",
  ui_story_5010_50100401_20_dialog_content = "Are you sure this is an ambush? I still sense a lot of them nearby! Stay on your guard...",
  ui_story_5010_50100401_21_dialog_content = "Accept your punishment!",
  ui_story_5010_50100401_22_dialog_content = "Graaaugh...!",
  ui_story_5010_50100401_23_dialog_content = "<color=#FFB400>Pittman</color>!",
  ui_story_5010_50100401_24_dialog_content = "Lumopolis... Why have they seen fit to send someone from the Hall of Justice here?",
  ui_story_5010_50100401_25_dialog_content = "The scent of this creature... Thanks to it, I was finally able to find this place.",
  ui_story_5010_50100401_26_dialog_content = "That's Wayne Pittman, an investigator from the Hall of Justice. We once fought side by side, Bethel.",
  ui_story_5010_50100401_27_dialog_content = "Greetings, Mr. Pittman of Lumopolis. I am Bethel, the head of the Umbraton Guild.",
  ui_story_5010_50100401_28_dialog_content = "Were you searching for something here in Umbraton? If you were looking for the road back to Lumopolis, I would be happy to show you.",
  ui_story_5010_50100401_29_dialog_content = "... Rest assured, I'm not here with any ill intent. My current investigation has nothing to do with any of you.",
  ui_story_5010_50100401_30_dialog_content = "The Eclipsites just now... Did any of you see exactly how they appeared here?",
  ui_story_5010_50100401_31_dialog_content = "It was very sudden, and the guards were unable to respond in time. These Eclipsites were more powerful than usual, and seemed to be quite familiar with the headquarters.",
  ui_story_5010_50100401_32_dialog_content = "I was standing outside. I actually saw an ordinary person suddenly turning into one...",
  ui_story_5010_50100401_33_dialog_content = "Hmm... Just as I thought.",
  ui_story_5010_50100401_34_dialog_content = "<color=#FFB400>Enhancers</color>.",
  ui_story_5010_50100401_35_dialog_content = "I'm sorry, En-what?",
  ui_story_5010_50100401_36_dialog_content = "When these Eclipsites appeared, did any of them exhibit strange or erratic behavior?",
  ui_story_5010_50100401_37_dialog_content = "I didn't really see anything. What about you, Bethel?",
  ui_story_5010_50100401_38_dialog_content = "One moment, Frankel has detected something...",
  ui_story_5010_50100401_39_dialog_content = "Graaaaaaagh!!",
  ui_story_5010_50100401_40_dialog_content = "A pity... I just missed another chance to see it use the enhancer.",
  ui_story_5010_50100401_41_dialog_content = "Perhaps if we cut it open, we might still discover something?",
  ui_story_5010_50100401_42_dialog_content = "You're not going to help, Luke?",
  ui_story_5010_50100401_43_dialog_content = "My job is to protect you, not to help a Lumopolis officer or fight his battles.",
  ui_story_5010_50100402_1_dialog_content = "Thanks for your assistance, Mr. Pittman.",
  ui_story_5010_50100402_2_dialog_content = "But how exactly did they do it? How could their speed and power increase all of a sudden?",
  ui_story_5010_50100402_3_dialog_content = "What we refer to as the enhancer. It's a powerful drug that grants Aurorians the power of an Eclipsite, if only for a short while.",
  ui_story_5010_50100402_4_dialog_content = "More concerning, however, is that those who ingest those enhancers will turn into Eclipsites themselves.",
  ui_story_5010_50100402_5_dialog_content = "No wonder the ones waiting to ambush us couldn't help themselves once Frankel walked past... Guess they don't have much time for patience.",
  ui_story_5010_50100402_6_dialog_content = "That means, if we had been the ones who walked past them... We would've been in real trouble.",
  ui_story_5010_50100402_7_dialog_content = "Whew, that was close... I'm back, Lady Bethel! It seems the Eclipsites have been all but exterminated...",
  ui_story_5010_50100402_8_dialog_content = "Lady Bethel! We're here!",
  ui_story_5010_50100402_9_dialog_content = "Guard this place, all of you! Seth!",
  ui_story_5010_50100402_10_dialog_content = "Yes, my lady!",
  ui_story_5010_50100402_11_dialog_content = "Go to the Shadowlord and request more guards!",
  ui_story_5010_50100402_12_dialog_content = "Understood!",
  ui_story_5010_50100402_13_dialog_content = "The use of an enhancer to transform and temporarily increase one's combat power... Does this sound familiar to you, PlayerName?",
  ui_story_5010_50100402_14_dialog_content = "Could it be...?",
  ui_story_5010_50100402_15_dialog_content = "It is. From the day we parted ways in Eraveil, I have been pursuing my investigation on these transformations...",
  ui_story_5010_50100402_16_dialog_content = "And ultimately, my investigation has led me here, to Umbraton...",
  ui_story_5010_50100402_17_dialog_content = "As it stands, the effects of this enhancer are strikingly similar to the grotesque modification we met before. Therefore, it is likely that they share an origin.",
  ui_story_5010_50100402_18_dialog_content = "Could the origin of these dark and twisted arts lie in Umbraton?",
  ui_story_5010_50100402_19_dialog_content = "I don't think this enhancer is from Umbraton, Mr. Pittman. I'm in charge of the Umbraton Guild, and I've never even heard of it!",
  ui_story_5010_50100402_20_dialog_content = "Agreed. I haven't heard so much as a whisper about anything like this.",
  ui_story_5010_50100402_21_dialog_content = "Besides, Eclipsite attacks aren't exactly uncommon around here. This is Umbraton, not some cushy paradise in the sky.",
  ui_story_5010_50100402_22_dialog_content = "In any case, I am thankful that you are unharmed, PlayerName. I could never explain it to the Shadowlord if something were to happen to you.",
  ui_story_5010_50100402_23_dialog_content = "Shadowlord... Shadowlord... Yes, that reminds me.",
  ui_story_5010_50100402_24_dialog_content = "What are you talking about now, Pittman?",
  ui_story_5010_50100402_25_dialog_content = "If anyone fully understands the happenings in Umbraton, it is the Shadowlord himself. I must see him.",
  ui_story_5010_50100402_26_dialog_content = "I will go make my report to Mr. Istvan, and wait for his orders.",
  ui_story_5010_50100402_27_dialog_content = "What makes you so sure that Umbraton is the source of your problem, Pittman?",
  ui_story_5010_50100402_28_dialog_content = "You need to calm down, Luke... He has his own job to do, too...",
  ui_story_5010_50100402_29_dialog_content = "Let's set things straight instead of quarreling here.",
  ui_story_5010_50100402_30_dialog_content = "We have enemies that can turn into Eclipsites now, but their numbers and motives are still unknown.",
  ui_story_5010_50100402_31_dialog_content = "Given our current circumstances, PlayerName... I believe we must postpone our earlier business until a later date. Is that acceptable?",
  ui_story_5010_50100402_32_dialog_content = "To be honest, it'd probably be a lot easier to leave them here than carry it all over the place.",
  ui_story_5010_50100402_33_dialog_content = "Agreed. I'm going to hit the station up to see if any strange people have appeared in the city lately.",
  ui_story_5010_50100402_34_dialog_content = "The station?",
  ui_story_5010_50100402_35_dialog_content = "It's the go-to place for information around here.",
  ui_story_5010_50100402_36_dialog_content = "I don't think it's too far from here, either... Why not come with me, PlayerName? I can't leave you alone, anyway.",
  ui_story_5010_50100402_37_dialog_content = "Excuse me, would I be able to inquire about the enhancers at your station?",
  ui_story_5010_50100402_38_dialog_content = "Maybe, but I can't say for sure. Couldn't hurt to try your luck, though.",
  ui_story_5010_50100402_39_dialog_content = "There's an intersection in the center of the town, where they hang blue lights over the streets. The place we're going to is a bar on the corner of the street, conveniently named The Crossroads.",
  ui_story_5010_50100402_40_dialog_content = "How fitting...",
  ui_story_5010_50100402_41_dialog_content = "The bar sees all kinds of folks, so make sure you're ready before we go in.",
  ui_story_5010_50100402_42_dialog_content = "I doubt they could be any worse than the enhanced Eclipsites we fought today.",
  ui_story_5010_50100402_43_dialog_content = "We just want to know who's giving out those enhancers. I don't think there are Eclipsites in a bar.",
  ui_story_5010_50100402_44_dialog_content = "I will protect PlayerName. Feel free to investigate, Mr. Pittman... on your own.",
  ui_story_5010_50100402_45_dialog_content = "An intersection with blue lights... Strange, I don't remember noticing a place like that before?",
  ui_story_5010_50100402_46_dialog_content = "It's only been around for a few years. Maybe you were still studying abroad when it opened?",
  ui_story_5010_50100402_47_dialog_content = "We can go together, then. Perhaps we'll learn more about who launched an attack on the Guild.",
  ui_story_5010_50100402_48_dialog_content = "Er... Fine, have it your way, Miss Bethel. But please, once we arrive...",
  ui_story_5010_50100402_49_dialog_content = "Be careful what you say and do in there.",
  ui_story_5010_50100501_1_dialog_content = "The Crossroads can be a complicated place, so it's in everyone's best interest to mind their words.",
  ui_story_5010_50100501_2_dialog_content = "Not a problem.",
  ui_story_5010_50100501_3_dialog_content = "It's completely silent around here... Is it even open?",
  ui_story_5010_50100501_4_dialog_content = "The blue light's on, so it should be. It is strange, though... Usually, you can hear the ruckus from at least three blocks away...",
  ui_story_5010_50100501_5_dialog_content = "In any case, stay on your guard once we're inside.",
  ui_story_5010_50100501_6_dialog_content = "The door is, indeed, open...",
  ui_story_5010_50100501_X6_dialog_content = "Excuse me!",
  ui_story_5010_50100501_7_dialog_content = "Bethel, you're supposed to order from the bar...",
  ui_story_5010_50100501_8_dialog_content = "...",
  ui_story_5010_50100501_9_dialog_content = "Whatchu lookin' at?!",
  ui_story_5010_50100501_10_dialog_content = "Whoa!",
  ui_story_5010_50100501_11_dialog_content = "PlayerName! Get over here!",
  ui_story_5010_50100501_12_dialog_content = "You, uh... Might want to keep your distance from them. Wait for me here, okay?",
  ui_story_5010_50100501_13_dialog_content = "Okay... You're the boss.",
  ui_story_5010_50100501_14_dialog_content = "Good evening.",
  ui_story_5010_50100501_15_dialog_content = "...",
  ui_story_5010_50100501_16_dialog_content = "I am Pittman, an investigator from Lumopolis.",
  ui_story_5010_50100501_17_dialog_content = "I would like to ask you all a few questions. Your cooperation is most appreciated.",
  ui_story_5010_50100501_18_dialog_content = "?!?!",
  ui_story_5010_50100501_19_dialog_content = "W-Wayne! You can't just ask out of nowhere like that!!",
  ui_story_5010_50100501_20_dialog_content = "...",
  ui_story_5010_50100501_21_dialog_content = "...",
  ui_story_5010_50100501_22_dialog_content = "Whoa! Wh-When did they get so close to us?!",
  ui_story_5010_50100501_23_dialog_content = "What do you think you're doing? Get back, PlayerName!",
  ui_story_5010_50100501_24_dialog_content = "What're you scared of, kid? It's not like I'm gonna eat you.",
  ui_story_5010_50100501_25_dialog_content = "Our boss wants a word with you two. Have a seat with him, would ya?",
  ui_story_5010_50100501_26_dialog_content = "...",
  ui_story_5010_50100501_27_dialog_content = "...",
  ui_story_5010_50100501_28_dialog_content = "Long time no see, Mr. Rhein.",
  ui_story_5010_50100501_29_dialog_content = "Lady Bethel... A slow day at work, I assume?",
  ui_story_5010_50100501_30_dialog_content = "There is no work to be done today, not with the incident that happened at the headquarters earlier. As for you...",
  ui_story_5010_50100501_31_dialog_content = "How has business been for the <color=#FFB400>Blue Lion Guild</color> lately?",
  ui_story_5010_50100501_32_dialog_content = "Hahaha, it's a living, you know! Nothing more!",
  ui_story_5010_50100501_33_dialog_content = "There's no need to be so uptight! We're just chatting, that's all!",
  ui_story_5010_50100501_34_dialog_content = "Then let us start. What exactly do you wish to chat about?",
  ui_story_5010_50100501_35_dialog_content = "Will it be about the enhancers, or the attack on our Guild earlier today?",
  ui_story_5010_50100501_36_dialog_content = "I have no interest in chatting about anything else.",
  ui_story_5010_50100501_37_dialog_content = "What's this? A chat over drinks with the head of Blue Lion Guild, and I wasn't invited? I thought we are together here, you know?",
  ui_story_5010_50100501_38_dialog_content = "A White Flame mercenary, an investigator from the Hall of Justice, the head of the Umbraton Guild, and...",
  ui_story_5010_50100501_39_dialog_content = "... A helpless runt who can't use any form of Luminatics.",
  ui_story_5010_50100501_40_dialog_content = "Quite the motley crew you have here, Lady Bethel.",
  ui_story_5010_50100501_41_dialog_content = "Didn't stop us from wiping out a legion of Eclipsites earlier, you know...",
  ui_story_5010_50100501_42_dialog_content = "Indeed.",
  ui_story_5010_50100501_43_dialog_content = "I'm sorry, but I wasn't speaking to you, Luke. The head of a defunct gang of mercenary dogs is still just a dog, so why don't you chew on a bone and leave the talking to us?",
  ui_story_5010_50100501_44_dialog_content = "!!",
  ui_story_5010_50100501_45_dialog_content = "Rhein.",
  ui_story_5010_50100501_46_dialog_content = "We're here to find information, not to fight. If you have nothing to give, I believe there are plenty of people we can talk to.",
  ui_story_5010_50100501_47_dialog_content = "I don't. I've heard nothing all night.",
  ui_story_5010_50100501_48_dialog_content = "In that case, this chat ends here.",
  ui_story_5010_50100501_49_dialog_content = "Let's go, Bethel.",
  ui_story_5010_50100501_50_dialog_content = "...",
  ui_story_5010_50100501_51_dialog_content = "Phew, that was intense. He just ignored an investigator from Lumopolis... They really aren't afraid of the law, are they?",
  ui_story_5010_50100501_52_dialog_content = "Well, the Blue Lion Guild is indeed powerful. They have accumulated both money and manpower in excess lately...",
  ui_story_5010_50100501_53_dialog_content = "But their business would never have prospered without Guild Headquarters. After all, every trade route is under our control.",
  ui_story_5010_50100501_54_dialog_content = "...",
  ui_story_5010_50100501_55_dialog_content = "Are you alright, Luke?",
  ui_story_5010_50100501_56_dialog_content = "Rhein has never been too fond of us mercenaries, but the Blue Lion Guild's way too powerful now... We can't really do anything to him.",
  ui_story_5010_50100501_57_dialog_content = "I heard he's opened up a few unofficial trade routes for himself, and they've been raking in the profits.",
  ui_story_5010_50100501_58_dialog_content = "As to what exactly is being sold, there haven't been any reports to the Guild Headquarters about it...",
  ui_story_5010_50100501_59_dialog_content = "What?",
  ui_story_5010_50100501_60_dialog_content = "It seems that a proper investigation on the Blue Lion Guild is in order.",
  ui_story_5010_50100501_61_dialog_content = "!!",
  ui_story_5010_50100501_62_dialog_content = "Seth? What's the matter?",
  ui_story_5010_50100501_63_dialog_content = "Shadow... Just now... Found him!",
  ui_story_5010_50100501_64_dialog_content = "What are you trying to say? Compose yourself!",
  ui_story_5010_50100501_65_dialog_content = "The Shadowlord! He... He was attacked...!",
  ui_story_5010_50100501_66_dialog_content = "...",
  ui_story_5010_50100501_67_dialog_content = "!!!",
  ui_story_5010_50100501_68_dialog_content = "Bethel? What's going on?",
  ui_story_5010_50100501_69_dialog_content = "Woof! Woof, woof!!",
  ui_story_5010_50100501_70_dialog_content = "Wait... Who is that ahead?",
  ui_story_5010_50100501_71_dialog_content = "Look out, PlayerName!!",
  ui_story_5010_50100501_72_dialog_content = "Bwahahahaha!",
  ui_story_5010_50100501_73_dialog_content = "That familiar scent again...",
  ui_story_5010_50100501_74_dialog_content = "That <color=#FFB400>pill</color>... Don't tell me...!",
  ui_story_5010_50100501_75_dialog_content = "That... That's right! Graaaah!",
  ui_story_5010_50100501_76_dialog_content = "He... He turned into an Eclipsite!!!",
  ui_story_5010_50100501_77_dialog_content = "Bethel!",
  ui_story_5010_50100501_78_dialog_content = "I can't reach the Shadowlord! He is likely under attack, as well!",
  ui_story_5010_50100501_79_dialog_content = "The enemy is attacking! Get ready for battle! ... Bethel, Do you hear me?!",
  ui_story_5010_50100501_80_dialog_content = "... Drat. I can't get through to Seth either.",
  ui_story_5010_50100501_81_dialog_content = "You and I will hold them off, Wayne!",
  ui_story_5010_50100501_82_dialog_content = "Try to capture one alive, is that possible?",
  ui_story_5010_50100502_1_dialog_content = "These Eclipsites... No, they're people of Umbraton who look like Eclipsites. Is this what the pill does...?",
  ui_story_5010_50100502_2_dialog_content = "Have you all seen the transformation clearly? They turn into creatures more powerful than ordinary Eclipsites.",
  ui_story_5010_50100502_3_dialog_content = "Is this the modification you were talking about before?",
  ui_story_5010_50100502_4_dialog_content = "Strictly speaking, it is a kind of modification, yes.",
  ui_story_5010_50100502_5_dialog_content = "Are you certain you know nothing more about these enhancers? Has Umbraton truly never experienced this kind of danger in the past?",
  ui_story_5010_50100502_6_dialog_content = "Not that I know of, no. This has to be a relatively recent development, or else the whole city would be in a state of panic right now.",
  ui_story_5010_50100502_7_dialog_content = "Even now, I'm still having trouble believing it. For a person to turn into an Eclipsite just like that...",
  ui_story_5010_50100502_8_dialog_content = "It would appear that the Blue Lion Guild is somehow connected to all of this.",
  ui_story_5010_50100502_9_dialog_content = "Yeah, I agree. This can't be just a coincidence.",
  ui_story_5010_50100502_10_dialog_content = "Unfortunately, I can ascertain nothing about the identities of these people in their transformed state. They left no clues behind, either...",
  ui_story_5010_50100502_11_dialog_content = "I will continue my investigation here, and follow Rhein's movements for the time being.",
  ui_story_5010_50100502_12_dialog_content = "Hey... Where's Bethel?",
  ui_story_5010_50100502_13_dialog_content = "Bethel! Where have you been?",
  ui_story_5010_50100502_14_dialog_content = "The Shadowlord's situation is still unclear. All I know is that he has been attacked!",
  ui_story_5010_50100502_15_dialog_content = "I must go to him.",
  ui_story_5010_50100502_16_dialog_content = "Are you alright?",
  ui_story_5010_50100502_17_dialog_content = "Please forgive me, PlayerName... We will have to further postpone the matter of your inheritance. We will discuss it upon my return.",
  ui_story_5010_50100502_18_dialog_content = "I'm sorry.",
  ui_story_5010_50100502_19_dialog_content = "Shadowlord was attacked? Could it be the Blue Lion Guild...?",
  ui_story_5010_50100502_20_dialog_content = "I am uncertain, but we will handle our own affairs, thank you.",
  ui_story_5010_50100502_21_dialog_content = "...",
  ui_story_5010_50100502_22_dialog_content = "So what's the plan now, PlayerName?",
  ui_story_5010_50100502_23_dialog_content = "Seems like we can't do much for either of them right now.",
  ui_story_5010_50100502_24_dialog_content = "Oh, right! There's still the underground auction!",
  ui_story_5010_50100502_25_dialog_content = "Yeah, that reminds me... What exactly are you looking for at this auction?",
  ui_story_5010_50100502_26_dialog_content = "A set of simulation room components. Naroxel told me about them.",
  ui_story_5010_50100502_27_dialog_content = "They're crucial parts for a Colossus, and Soroz might be able to use them.",
  ui_story_5010_50100502_28_dialog_content = "Got it. In that case, do exactly as I say once we get there.",
  ui_story_5010_50100502_29_dialog_content = "We can't afford to have any more things go wrong today!",
  ui_story_5010_50100601_1_dialog_content = "We're almost there, PlayerName.",
  ui_story_5010_50100601_2_dialog_content = "Luke... Wh-What should I do? Should I go talk to the auctioneer?",
  ui_story_5010_50100601_3_dialog_content = "No way! Every participant in these underground auctions is completely anonymous. You have to go through the organizer to gain access.",
  ui_story_5010_50100601_4_dialog_content = "See, the seller gives his items to the organizer, and then the buyers and the organizer...",
  ui_story_5010_50100601_5_dialog_content = "Oh, I get it now. We have to go up to the organizer and make an offer, is that it?",
  ui_story_5010_50100601_6_dialog_content = "As if it were that easy! The organizer will set up an anonymous auction on a given date, and the sale goes to the highest bidder.",
  ui_story_5010_50100601_7_dialog_content = "On a given date? So we have to wait for the auction to take place...",
  ui_story_5010_50100601_8_dialog_content = "Not exactly. We can go find the organizer to get some details out of them. With any luck, we might even get to see the goods...",
  ui_story_5010_50100601_9_dialog_content = "I understand. Then it's just a matter of showing up to the auction and making a high offer on them, right?",
  ui_story_5010_50100601_10_dialog_content = "As I said, PlayerName, the buyers at these auctions must maintain total anonymity too... So if you want to bid on anything, the process is a little more complicated than that.",
  ui_story_5010_50100601_11_dialog_content = "Total anonymity? Even for the buyers?",
  ui_story_5010_50100601_12_dialog_content = "Of course! If you manage to buy something valuable and everyone knows who you are, you're basically asking to get robbed.... Or worse.",
  ui_story_5010_50100601_13_dialog_content = "Anyways, it would take me hours to explain everything. It'd be better for us to go take a look first.",
  ui_story_5010_50100601_14_dialog_content = "Okay, Luke.",
  ui_story_5010_50100601_15_dialog_content = "Here's a list of items that will be sold soon, as well as their auction dates. Take a look, PlayerName.",
  ui_story_5010_50100601_16_dialog_content = "That person just now...",
  ui_story_5010_50100601_17_dialog_content = "It doesn't matter.",
  ui_story_5010_50100601_18_dialog_content = "They probably won't host an auction for those simulation room components you're looking for anytime soon. Maybe we can try asking the seller's starting price first.",
  ui_story_5010_50100601_19_dialog_content = "The stuff on this list... How... How could anyone even think of...",
  ui_story_5010_50100601_20_dialog_content = "Hahahaha! There's a reason this is an underground auction, you know!",
  ui_story_5010_50100601_21_dialog_content = "How do they even come across this kind of stuff?",
  ui_story_5010_50100601_22_dialog_content = "Hmm... That's the seller's business, nobody knows. They could've excavated it, or made it themselves... Or they could've stolen it.",
  ui_story_5010_50100601_23_dialog_content = "Wait... So nobody cares how they came across this stuff?!",
  ui_story_5010_50100601_24_dialog_content = "Hah, what do you think?",
  ui_story_5010_50100601_25_dialog_content = "And people aren't worried about giving the stuff they secretly have to the auction organizers?",
  ui_story_5010_50100601_26_dialog_content = "Well, the underground auction has been here for years. They have some degree of credibility, you know?",
  ui_story_5010_50100601_27_dialog_content = "It's pretty busy... Are all these people here to see the goods up for auction?",
  ui_story_5010_50100601_28_dialog_content = "Keep it down!",
  ui_story_5010_50100601_29_dialog_content = "Judging from everyone's behavior, it looks like they're here to bid on today's auction.",
  ui_story_5010_50100601_30_dialog_content = "There are tons of people here... many of them are the bigwigs in Umbraton.",
  ui_story_5010_50100601_31_dialog_content = "... Huh? Those people over there...",
  ui_story_5010_50100601_32_dialog_content = "Faust? And Beryl? ... Even Paloma, too?!",
  ui_story_5010_50100601_33_dialog_content = "Whoa... I was surprised to find out you knew Faust, PlayerName...",
  ui_story_5010_50100601_34_dialog_content = "But I never would've guessed you knew those ladies from the True Order, too?",
  ui_story_5010_50100601_35_dialog_content = "It's a long story, that's for sure...",
  ui_story_5010_50100601_36_dialog_content = "<color=#e8d9bb>Pitter-patter...</color>",
  ui_story_5010_50100601_37_dialog_content = "It's starting to rain...? Come on, Luke, let's get inside!",
  ui_story_5010_50100601_38_dialog_content = "Yeah, sure.",
  ui_story_5010_50100601_39_dialog_content = "So, it finally rains...",
  ui_story_5010_50100601_40_dialog_content = "...",
  ui_story_5010_50100601_41_dialog_content = "...",
  ui_story_5010_50100601_42_dialog_content = "...",
  ui_story_5010_50100601_43_dialog_content = "(It's so quiet...)",
  ui_story_5010_50100601_44_dialog_content = "This way, PlayerName. That is where the auctions take place. We're looking for the organizer, remember?",
  ui_story_5010_50100601_45_dialog_content = "By the way... Will you be able to tell if these parts are fakes or not, PlayerName?",
  ui_story_5010_50100601_46_dialog_content = "The organizer says that the parts have been appraised by technicians from both Illumina and the Rediesel Wrench. Here's the certificate.",
  ui_story_5010_50100601_47_dialog_content = "Huh, no kidding...",
  ui_story_5010_50100601_48_dialog_content = "Both of these people are friends of mine, Luke. These must be the real deal!",
  ui_story_5010_50100601_49_dialog_content = "Alright, then it looks like the next step is to register for their auction as potential buyers.",
  ui_story_5010_50100601_50_dialog_content = "So, how much are you willing to spend on these parts, PlayerName?",
  ui_story_5010_50100601_51_dialog_content = "... <size=45>678 Nightium?!</size>",
  ui_story_5010_50100601_52_dialog_content = "Uh... W-Well... That ought to be about a thousandth of the seller's asking price...",
  ui_story_5010_50100601_53_dialog_content = "B-But that's all the money I have on me right now...",
  ui_story_5010_50100601_54_dialog_content = "I see... Looks like we'll have to go back and think of something else.",
  ui_story_5010_50100601_55_dialog_content = "Thankfully, the auction for those components isn't going to start for a while.",
  ui_story_5010_50100601_56_dialog_content = "RIght...",
  ui_story_5010_50100601_57_dialog_content = "I wouldn't worry too much about it. If we can find something of high enough value, we might be able to negotiate with the seller...",
  ui_story_5010_50100601_58_dialog_content = "<size=45><color=#e8d9bb>Bang!</color></size>",
  ui_story_5010_50100601_59_dialog_content = "What was that noise just now?",
  ui_story_5010_50100601_60_dialog_content = "It came from the auction room... I have a bad feeling about this.",
  ui_story_5010_50100601_61_dialog_content = "Come on, let's go take a look!",
  ui_story_5010_50100601_62_dialog_content = "W-Wait, sir! You can't just...",
  ui_story_5010_50100601_63_dialog_content = "Can't just what? Do this?",
  ui_story_5010_50100601_64_dialog_content = "<size=45><color=#e8d9bb>Bang! Bang!</color></size>",
  ui_story_5010_50100601_65_dialog_content = "Shots fired?!",
  ui_story_5010_50100601_66_dialog_content = "Get down! Don't move...",
  ui_story_5010_50100601_67_dialog_content = "Sorry to interrupt, everyone...",
  ui_story_5010_50100601_68_dialog_content = "What do you think you're doing?!",
  ui_story_5010_50100601_69_dialog_content = "Shh... Please stay silent, if you would.",
  ui_story_5010_50100601_70_dialog_content = "We've come to make an announcement, nothing more. There is no cause for panic...",
  ui_story_5010_50100601_71_dialog_content = "Please, Maude, if I may? I've wanted to say these words for... Oh, so long...",
  ui_story_5010_50100601_72_dialog_content = "Now then... From this day forth, I, Rhein, will serve as Umbraton's new...",
  ui_story_5010_50100601_73_dialog_content = "<color=#FFB400>Ruler</color>.",
  ui_story_5010_50100601_74_dialog_content = "?!",
  ui_story_5010_50100601_75_dialog_content = "That guy next to Rhein is Maude, the leader of a local gang called Solus.",
  ui_story_5010_50100601_76_dialog_content = "Solus is one of the most powerful gangs here in Umbraton. I would never have guessed they'd throw their hat in with the Blue Lion Guild.",
  ui_story_5010_50100601_77_dialog_content = "Rhein, Maude... What are you going on about?!",
  ui_story_5010_50100601_78_dialog_content = "Didn't we ask you...",
  ui_story_5010_50100601_79_dialog_content = "To shut your mouth!!",
  ui_story_5010_50100601_80_dialog_content = "Why do you have to make me shout like some lowly commoner...",
  ui_story_5010_50100601_81_dialog_content = "Let's try this again... Attention, everyone! A grand revolution is about to begin, and I will be the one to lead Umbraton into a glorious new age!",
  ui_story_5010_50100601_82_dialog_content = "It is my distinct honor to discuss the future of Umbraton with the esteemed Guild leaders gathered here today...",
  ui_story_5010_50100601_83_dialog_content = "As for the Shadowlord, whom I'm certain everyone is currently whispering about, I can assure you all that he and his beloved airship... Are a part of our city's rich history now.",
  ui_story_5010_50100601_84_dialog_content = "What have you done?!",
  ui_story_5010_50100601_85_dialog_content = "What's he talking about, Luke?",
  ui_story_5010_50100601_86_dialog_content = "Didn't you hear him? Rhein's starting a rebellion!",
  ui_story_5010_50100601_87_dialog_content = "Darn... Our terminals aren't working at all! This has to be Rhein's doing...",
  ui_story_5010_50100601_88_dialog_content = "We need to find a way to get the news out!",
  ui_story_5010_50100601_89_dialog_content = "But where is Rhein's confidence coming from? Does he really think he can beat all the bosses here?",
  ui_story_5010_50100601_90_dialog_content = "Look over there, Luke!",
  ui_story_5010_50100601_91_dialog_content = "Heavens... That's a lot of transformed Eclipsites!",
  ui_story_5010_50100601_92_dialog_content = "Please refrain from any pointless acts of resistance!",
  ui_story_5010_50100601_93_dialog_content = "As representative of the Blue Lion Guild... No, of ALL of Umbraton... Please accept my sincerest apologies for this disorderly scene.",
  ui_story_5010_50100601_94_dialog_content = "Now then, dearest leaders of Umbraton's many Guilds, as well as all other esteemed guests from afar, I humbly demand your unconditional surrender and the acceptance of the following terms!",
  ui_story_5010_50100601_95_dialog_content = "Luke, we...",
  ui_story_5010_50100601_96_dialog_content = "I'll cover you while you look for a way out. After that, it's up to you to get help for all of us.",
  ui_story_5010_50100601_97_dialog_content = "Eh? What are you doing?!",
  ui_story_5010_50100601_98_dialog_content = "...?",
  ui_story_5010_50100601_99_dialog_content = "It seems... You don't need this arm anymore!",
  ui_story_5010_50100601_100_dialog_content = "Aaaaaaaargh!!!",
  ui_story_5010_50100601_101_dialog_content = "The True Order...?",
  ui_story_5010_50100601_102_dialog_content = "...",
  ui_story_5010_50100601_103_dialog_content = "This was supposed to be a normal auction, and you ruined it...",
  ui_story_5010_50100601_104_dialog_content = "C-Calm down, Paloma! You've already knocked him unconscious...",
  ui_story_5010_50100601_105_dialog_content = "Mr. Rhein, the rules prohibit any kind of noisy disruption at these auctions. I'm afraid... We will have to ask you to leave.",
  ui_story_5010_50100601_106_dialog_content = "... And who might you be? Am I supposed to know who you are?",
  ui_story_5010_50100601_107_dialog_content = "Enough of this nonsense. Kill them all.",
  ui_story_5010_50100601_108_dialog_content = "Beryl! Paloma!",
  ui_story_5010_50100601_109_dialog_content = "PlayerName?!",
  ui_story_5010_50100601_110_dialog_content = "We meet again, my friend. A pity it has to be under such awful circumstances.",
  ui_story_5010_50100601_111_dialog_content = "You again, Caelestite... But where have your associates gone?",
  ui_story_5010_50100601_112_dialog_content = "...",
  ui_story_5010_50100601_113_dialog_content = "... Ah, but I suppose this was to be expected. I didn't want to resort to violence, you know?",
  ui_story_5010_50100601_114_dialog_content = "Tch.",
  ui_story_5010_50100601_115_dialog_content = "I will dispose of the ones over here. You can have the rest.",
  ui_story_5010_50100601_116_dialog_content = "Yes, sir!",
  ui_story_5010_50100601_117_dialog_content = "Here, take these as well.",
  ui_story_5010_50100601_118_dialog_content = "Ah! Th-Thank you, boss! All this good stuff...",
  ui_story_5010_50100601_119_dialog_content = "Don't let a single pill go to waste! For Umbraton's new order!",
  ui_story_5010_50100601_120_dialog_content = "Graaaaaagh!!!",
  ui_story_5010_50100601_121_dialog_content = "That man... Did he just turn into an Eclipsite?!",
  ui_story_5010_50100601_122_dialog_content = "Orders, PlayerName!",
  ui_story_5010_50100601_123_dialog_content = "Leave it to me! Faust, you make sure those two don't get away!",
  ui_story_5010_50100601_124_dialog_content = "What's this? You mean to capture us?",
  ui_story_5010_50100601_125_dialog_content = "Hahahaha! What a gutsy kid!",
  ui_story_5010_50100601_126_dialog_content = "Hey, why are you laughing? I have some questions for you, now get over here!",
  ui_story_5010_50100601_127_dialog_content = "Stay back, you madwoman.",
  ui_story_5010_50100601_128_dialog_content = "What did you call me...?",
  ui_story_5010_50100601_129_dialog_content = "*Sigh* This is going to get ugly.",
  ui_story_5010_50100602_1_dialog_content = "... Condemn!",
  ui_story_5010_50100602_2_dialog_content = "Uraaaagh...!",
  ui_story_5010_50100602_3_dialog_content = "Ah... Pittman! You're here!",
  ui_story_5010_50100602_4_dialog_content = "Pittman?",
  ui_story_5010_50100602_5_dialog_content = "Good evening to you as well, Paloma...",
  ui_story_5010_50100602_6_dialog_content = "Sanguine Crystal... This belongs to Beryl Gautier!",
  ui_story_5010_50100602_7_dialog_content = "Hello! I've heard much about you, Mr. Investigator!",
  ui_story_5010_50100602_8_dialog_content = "Miss Beryl Gautier... I am Wayne Pittman from the Lumo Hall of Justice, I must insist that you come with me this instant...",
  ui_story_5010_50100602_9_dialog_content = "Are you... arresting me?",
  ui_story_5010_50100602_10_dialog_content = "It seems you haven't made any progress in your investigation, Pittman...",
  ui_story_5010_50100602_11_dialog_content = "Uh... Paloma? Pittman didn't come here for you guys. He's here because of...",
  ui_story_5010_50100602_12_dialog_content = "The enhancers, or more precisely, the pills that those Blue Lion Guild members just swallowed...",
  ui_story_5010_50100602_13_dialog_content = "Wait, what are you talking about?",
  ui_story_5010_50100602_14_dialog_content = "Paloma... I fear that Mirren Gautier's modification technique is somehow connected to these enhancers.",
  ui_story_5010_50100602_15_dialog_content = "Mirren Gautier...",
  ui_story_5010_50100602_16_dialog_content = "We need to stop this now. The most important thing, for now, is not discussion.",
  ui_story_5010_50100602_17_dialog_content = "Where did Rhein go? Or that guy with the cane, for that matter?",
  ui_story_5010_50100602_18_dialog_content = "They must've slipped away.",
  ui_story_5010_50100602_19_dialog_content = "But why would they choose this auction as the target of their attack?",
  ui_story_5010_50100602_20_dialog_content = "I'm afraid the answer's not that easy. This must all be part of their plan.",
  ui_story_5010_50100602_21_dialog_content = "We're running out of time. We have to...",
  ui_story_5010_50100602_22_dialog_content = "Excuse me, friends. But I've found what we were looking for.",
  ui_story_5010_50100602_23_dialog_content = "You found it?",
  ui_story_5010_50100602_24_dialog_content = "Seeing as the Blue Lion Guild has already breached the rules of the auction...",
  ui_story_5010_50100602_25_dialog_content = "I figured we could get what we want and go now.",
  ui_story_5010_50100602_26_dialog_content = "I'm terribly sorry, PlayerName, but I believe these ladies and I must go our separate ways for now.",
  ui_story_5010_50100602_27_dialog_content = "Perhaps we will see each other again someday soon... May the Truth bless you.",
  ui_story_5010_50100602_28_dialog_content = "G-Goodbye, PlayerName...",
  ui_story_5010_50100602_29_dialog_content = "Oh! Uh, t-take care, you three!",
  ui_story_5010_50100602_30_dialog_content = "They're already gone... Does everyone in the True Order come and go like the wind?",
  ui_story_5010_50100602_31_dialog_content = "Beryl Gautier! Come back, Beryl Gautier...!",
  ui_story_5010_50100602_32_dialog_content = "Ah... Forget it. I'm certain Rhein still has more in store for us all, PlayerName.",
  ui_story_5010_50100602_33_dialog_content = "Our terminals are still down...",
  ui_story_5010_50100602_34_dialog_content = "Look over there. It's a smoke signal, and it's coming from the direction of the Guild Headquarters!",
  ui_story_5010_50100602_35_dialog_content = "Under normal circumstances, Umbraton's garrison troops would be immediately dispatched to control the situation.",
  ui_story_5010_50100602_36_dialog_content = "Can Umbraton's garrison troops really defeat an Enhancer?",
  ui_story_5010_50100602_37_dialog_content = "Er... Honestly? I don't think they stand a chance.",
  ui_story_5010_50100602_38_dialog_content = "We should make our way towards the headquarters and ascertain the situation.",
  ui_story_5010_50100602_39_dialog_content = "I agree... Lead the way, Luke!",
  ui_story_5010_50100602_40_dialog_content = "Come with me!",
  ui_story_5010_50100701_1_dialog_content = "The True Order... They're even more troublesome than I had anticipated.",
  ui_story_5010_50100701_2_dialog_content = "Nonetheless, the plan is set in motion, and victory is nearly ours.",
  ui_story_5010_50100701_3_dialog_content = "It would appear so, but I would prefer not to play our final <color=#FFB400>trump card</color>.",
  ui_story_5010_50100701_4_dialog_content = "Lady Bethel! Thank goodness! You have to save...!",
  ui_story_5010_50100701_5_dialog_content = "Hahahahaha!",
  ui_story_5010_50100701_6_dialog_content = "Who are you? How dare you attack the Umbraton Guild Headquarters!",
  ui_story_5010_50100701_7_dialog_content = "Heh... We're only acting under the new Shadowlord's order! The Umbraton Guild Headquarters belongs to him now!",
  ui_story_5010_50100701_8_dialog_content = "... Do you have any idea what you just said?",
  ui_story_5010_50100701_9_dialog_content = "Ha, of course I do, you foolish woman! Today's the day you die!!",
  ui_story_5010_50100701_10_dialog_content = "It seems you all are prepared to die for your cause.",
  ui_story_5010_50100701_11_dialog_content = "In that case...",
  ui_story_5010_50100701_12_dialog_content = "... Urgh!!",
  ui_story_5010_50100701_13_dialog_content = "I am happy to oblige.",
  ui_story_5010_50100701_14_dialog_content = "We didn't think you would be the one to answer our distress signal, Lady Bethel...",
  ui_story_5010_50100701_15_dialog_content = "There were so many of them just now. They said the new Shadowlord was in control of everything, and that we...",
  ui_story_5010_50100701_16_dialog_content = "Wait... Look out, everyone!",
  ui_story_5010_50100701_17_dialog_content = "This feeling... The feeling of overwhelming power! Hahahahaha!!!",
  ui_story_5010_50100701_18_dialog_content = "The fighting looks intense... The invaders must have forced their way into the main hall by now.",
  ui_story_5010_50100701_19_dialog_content = "That was Bethel's voice just now!",
  ui_story_5010_50100701_20_dialog_content = "Wait... I'm getting that strange feeling again... Is it...?",
  ui_story_5010_50100701_21_dialog_content = "It is! They're using enhancers again!",
  ui_story_5010_50100701_22_dialog_content = "Bethel!",
  ui_story_5010_50100701_23_dialog_content = "PlayerName! I'm over here!",
  ui_story_5010_50100701_24_dialog_content = "Ten times... No, twenty times... All of you, take a good look!",
  ui_story_5010_50100701_25_dialog_content = "Just how many pills did that guy take?",
  ui_story_5010_50100701_26_dialog_content = "We're coming, Bethel! Just hang on!",
  ui_story_5010_50100801_1_dialog_content = "Bethel! These guys are Maude's men! He and Rhein attacked the underground auction just now!",
  ui_story_5010_50100801_2_dialog_content = "Rhein said the Shadowlord... was history already.",
  ui_story_5010_50100801_3_dialog_content = "When you said the Shadowlord had been attacked earlier, what did you...",
  ui_story_5010_50100801_4_dialog_content = "I still haven't made contact with him, and the people I ordered to search for him have yet to send word.",
  ui_story_5010_50100801_5_dialog_content = "All I know is that there was an accident with the Shadowlord's airship...",
  ui_story_5010_50100801_6_dialog_content = "Then why are you here at headquarters?",
  ui_story_5010_50100801_7_dialog_content = "I saw the distress signal in the distance, and I came as quickly as I could.",
  ui_story_5010_50100801_8_dialog_content = "Lady Bethel! We are the garrison's first-responders...",
  ui_story_5010_50100801_9_dialog_content = "I know, I know. Have you brought us any news?",
  ui_story_5010_50100801_10_dialog_content = "The Blue Lion Guild, in conjunction with Solus, have staged an all-out coup.",
  ui_story_5010_50100801_11_dialog_content = "Targets of their armed insurgency include all major guilds, an underground auction, and the Shadowlord's mansion...",
  ui_story_5010_50100801_12_dialog_content = "Emergency measures have already been implemented, and...",
  ui_story_5010_50100801_13_dialog_content = "Has anyone been able to contact the Shadowlord himself?",
  ui_story_5010_50100801_14_dialog_content = "Due to the abnormal weather today, all terminals within the city are currently inoperable. We have been unable to establish contact with the Shadowlord, but the rumors mention that Rhein has already...",
  ui_story_5010_50100801_15_dialog_content = "Enough. Continue with your work.",
  ui_story_5010_50100801_16_dialog_content = "And watch out for those monsters! They can transform at any time!",
  ui_story_5010_50100801_17_dialog_content = "You lot! Find a way to restore communications within the city. We need to ascertain the situation in every sector, and rescue those who may yet be rescued!",
  ui_story_5010_50100801_18_dialog_content = "B-But Lady Bethel, our primary directive is to protect the inner city...",
  ui_story_5010_50100801_19_dialog_content = "...",
  ui_story_5010_50100801_20_dialog_content = "I'm sorry, but they were the Shadowlord's orders. Farewell, Lady Bethel.",
  ui_story_5010_50100801_21_dialog_content = "Heh, that's Lord Istvan for you.",
  ui_story_5010_50100801_22_dialog_content = "Have Rhein and his men lost their minds? How much power could they possibly have, that they are confident enough to challenge all of Umbraton at once?",
  ui_story_5010_50100801_23_dialog_content = "Umbraton isn't nearly as unified as you make it out to be, Bethel.",
  ui_story_5010_50100801_24_dialog_content = "Every guild, every gang... hell, every single person holds their own interests above everything else. Heh...",
  ui_story_5010_50100801_25_dialog_content = "I'm willing to bet that every single organization is thinking of a way to save their own right now. Some may even choose to side with Rhein, at this point.",
  ui_story_5010_50100801_26_dialog_content = "That's why he chose to personally attack the auction just now. With every major boss in attendance, he could get all of them involved in the chaos.",
  ui_story_5010_50100801_27_dialog_content = "Without consent from Lumopolis, could Rhein truly...",
  ui_story_5010_50100801_28_dialog_content = "Sorry to disappoint, Your Honor... But this is Umbraton.",
  ui_story_5010_50100801_29_dialog_content = "Everyone here upholds Umbraton's rules for their benefit. Everyone maintains orders around here because of Istvan's power.",
  ui_story_5010_50100801_30_dialog_content = "As far as most people are concerned, it doesn't matter who acts as the Shadowlord...",
  ui_story_5010_50100801_31_dialog_content = "But Rhein's playing this way too violently. If he takes over control of the city, I doubt anything good will come of it.",
  ui_story_5010_50100801_32_dialog_content = "Even if Rhein has truly defeated Istvan, and even if he conquers all of Umbraton, Lumopolis would never acknowledge...",
  ui_story_5010_50100801_33_dialog_content = "Ugh! There's no use talking about it now! Our main priority is to find the Shadowlord!",
  ui_story_5010_50100801_34_dialog_content = "But if Rhein's words were true, Bethel, then the Shadowlord...",
  ui_story_5010_50100801_35_dialog_content = "I refuse to believe any of it, Luke!",
  ui_story_5010_50100801_36_dialog_content = "Even if it doesn't matter who acts as Shadowlord of Umbraton... But for now, it must not be Rhein.",
  ui_story_5010_50100801_37_dialog_content = "You're right. More people are going to die if this keeps up. We have to stop him, no matter what he wants.",
  ui_story_5010_50100801_38_dialog_content = "I will go and gather the visitors from Lumopolis, and find a way to request support from the city.",
  ui_story_5010_50100801_39_dialog_content = "Look! That smoke signal is the one our mercenaries use in case of emergencies... And it's coming from the direction of the <color=#FFB400>Lin Family</color>!",
  ui_story_5010_50100801_40_dialog_content = "They don't keep many fighters in the city, which makes them one of the easiest targets to assault.",
  ui_story_5010_50100801_41_dialog_content = "The inner city's defense is solid. Even Rhein would be hard-pressed to break through.",
  ui_story_5010_50100801_42_dialog_content = "Huh? The Lin Guild might be under attack, too?",
  ui_story_5010_50100801_43_dialog_content = "I have to go help them!",
  ui_story_5010_50100801_44_dialog_content = "My job is still to protect you, PlayerName. If you go, I go.",
  ui_story_5010_50100801_45_dialog_content = "Everyone fends for themselves here in Umbraton... I'm afraid that we're the only ones here who can aid others.",
  ui_story_5010_50100801_46_dialog_content = "We go together, then!",
  ui_story_5010_50100901_1_dialog_content = "Y... You... Urgh...",
  ui_story_5010_50100901_2_dialog_content = "Hiss...",
  ui_story_5010_50100901_3_dialog_content = "Who's this?",
  ui_story_5010_50100901_4_dialog_content = "This is one of my men!",
  ui_story_5010_50100901_5_dialog_content = "L... Luke?",
  ui_story_5010_50100901_6_dialog_content = "Are you okay, brother? Who did this to you?!",
  ui_story_5010_50100901_7_dialog_content = "I'll survive, but Solus... They've already made their way in.",
  ui_story_5010_50100901_8_dialog_content = "The Lin Family's most powerful fighters are away from the city right now... All they can do is rely on the city's defense for now. It doesn't look good...",
  ui_story_5010_50100901_9_dialog_content = "Don't worry about that now. Just find a safe place and get some rest.",
  ui_story_5010_50100901_10_dialog_content = "...",
  ui_story_5010_50100901_11_dialog_content = "Inside... They took the enhancers again!",
  ui_story_5010_50100901_12_dialog_content = "We have to hurry!",
  ui_story_5010_50100901_13_dialog_content = "Looks like we'll have to clear out the whole place, huh? Sounds fun.",
  ui_story_5010_50100901_14_dialog_content = "Indeed. I can't wait...",
  ui_story_5010_50100901_15_dialog_content = "Chain! Extend!",
  ui_story_5010_50100901_16_dialog_content = "Roar!",
  ui_story_5010_50100902_1_dialog_content = "The rain is starting to pour in earnest now.",
  ui_story_5010_50100902_2_dialog_content = "Wait till the Lin Family comes home and sees what a mess it's become...",
  ui_story_5010_50100902_3_dialog_content = "Bethel.",
  ui_story_5010_50100902_4_dialog_content = "Hmm?",
  ui_story_5010_50100902_5_dialog_content = "I still don't understand... Why would the Blue Lion Guild join forces with Solus?",
  ui_story_5010_50100902_6_dialog_content = "It doesn't seem like Rhein or Maude really stand to gain anything by teaming up.",
  ui_story_5010_50100902_7_dialog_content = "Not only that, but they've clashed plenty of times in the past. After all, they both operate mostly underground, so they're constantly competing with each other.",
  ui_story_5010_50100902_8_dialog_content = "So if it's necessary for them to work together... why didn't they do it before?",
  ui_story_5010_50100902_9_dialog_content = "Why did they choose to wait until today to launch their coup...?",
  ui_story_5010_50100902_10_dialog_content = "The Shadowlord's travel itinerary. He was to depart from the city on his airship this morning...",
  ui_story_5010_50100902_11_dialog_content = "As well as this peculiar storm.",
  ui_story_5010_50100902_12_dialog_content = "Strange weather patterns that disrupt communications, as well as transformed Eclipsites... I've seen this before!",
  ui_story_5010_50100902_13_dialog_content = "In Dunefire... In Eraveil!",
  ui_story_5010_50100902_14_dialog_content = "Tell me, Bethel. What do you think could have motivated those two to put it all on the line like this?",
  ui_story_5010_50100902_15_dialog_content = "I can't imagine wrecking the city like this would serve them in any way...",
  ui_story_5010_50100902_16_dialog_content = "Unless it was to establish a monopoly on underground trade?",
  ui_story_5010_50100902_17_dialog_content = "But the Shadowlord has always turned a blind eye to these things. He has never taken a hard-line stance against them.",
  ui_story_5010_50100902_18_dialog_content = "Indeed, plenty of highly-questionable products flow freely through the shadows.",
  ui_story_5010_50100902_19_dialog_content = "That's why...",
  ui_story_5010_50100902_20_dialog_content = "Whatever motivates their coup must be even more attractive to them than a monopoly over underground trade.",
  ui_story_5010_50100902_21_dialog_content = "But what could it possibly be...",
  ui_story_5010_50100902_22_dialog_content = "Sorry to interrupt, Bethel, but I think Frankel...",
  ui_story_5010_50100902_23_dialog_content = "Fufufu...",
  ui_story_5010_50100902_24_dialog_content = "What is it, Frankel?",
  ui_story_5010_50100902_25_dialog_content = "Boo-foo...",
  ui_story_5010_50100902_26_dialog_content = "What's that over there? It's...",
  ui_story_5010_50100902_27_dialog_content = "Butterflies?",
  ui_story_5010_50100902_28_dialog_content = "Huh?",
  ui_story_5010_50100902_29_dialog_content = "There are a handful of butterflies under the eaves...",
  ui_story_5010_50100902_30_dialog_content = "This isn't the time to be nature-watching, Luke.",
  ui_story_5010_50100902_31_dialog_content = "Could you please turn your eagerness away from insects and towards rescuing our fellow Aurorians?",
  ui_story_5010_50100902_32_dialog_content = "... Something happened to the Steelfire Gang.",
  ui_story_5010_50100902_33_dialog_content = "W-Wait, who is the Steelfire Gang? And how do you know something happened to them?",
  ui_story_5010_50100902_34_dialog_content = "This type of butterfly is extremely sensitive to changes in temperature. It shouldn't exist here during this part of the year.",
  ui_story_5010_50100902_35_dialog_content = "But the Steelfire Gang had a greenhouse with a few of them in it. A while ago, I accepted a job to repair that very greenhouse.",
  ui_story_5010_50100902_36_dialog_content = "Look up at the eaves, and see for yourself.",
  ui_story_5010_50100902_37_dialog_content = "These butterflies... They're taking shelter from the rain here, and are drawn to our body heat.",
  ui_story_5010_50100902_38_dialog_content = "There's a good chance that the Steelfire Gang's greenhouse was opened... It must be some kind of signal!",
  ui_story_5010_50100902_39_dialog_content = "And a signal that only you would understand, Luke. How very strange...",
  ui_story_5010_50100902_40_dialog_content = "What will we find over there, I wonder?",
  ui_story_5010_50100902_41_dialog_content = "There's no telling... This is our only clue, after all.",
  ui_story_5010_50100902_42_dialog_content = "Indeed, even just to help maintain order... We cannot afford to sit idly.",
  ui_story_5010_50100902_43_dialog_content = "Thank goodness you were here to catch this, Luke.",
  ui_story_5010_50100902_44_dialog_content = "It's nothing. I pity these butterflies, though.",
  ui_story_5010_50100902_45_dialog_content = "At this temperature... They only have about half an hour before they die.",
  ui_story_5010_50100902_46_dialog_content = "The Steelfire Gang's base lies in low terrain, surrounded by slums.",
  ui_story_5010_50100902_47_dialog_content = "If they were attacked, I can only imagine the devastation...",
  ui_story_5010_50100902_48_dialog_content = "We won't find out by standing around here. Let's go.",
  ui_story_5010_50101002_1_dialog_content = "Thank goodness... We were able to rescue all of them.",
  ui_story_5010_50101002_2_dialog_content = "I never would have guessed Rhein and Maude left them untouched, as well.",
  ui_story_5010_50101002_3_dialog_content = "This makes no sense... It seems they left in a hurry before doing what they came to do.",
  ui_story_5010_50101002_4_dialog_content = "... Forget it, we need to tend to the wounded. Thankfully, their injuries are relatively minor.",
  ui_story_5010_50101002_5_dialog_content = "I left a signal for the White Flame Mercenaries, they should be here to provide support any minute.",
  ui_story_5010_50101002_6_dialog_content = "How did you manage to contact them?",
  ui_story_5010_50101002_7_dialog_content = "I left a trail of special mixtures behind us, one that doesn't wash away in the rain and even glows in the dark.",
  ui_story_5010_50101002_8_dialog_content = "... It must have something to do with your insects, I take it?",
  ui_story_5010_50101002_9_dialog_content = "That's right!",
  ui_story_5010_50101002_10_dialog_content = "Hold on, what's going on here...",
  ui_story_5010_50101002_11_dialog_content = "Run! Make for the top!",
  ui_story_5010_50101002_12_dialog_content = "Where has the Steelfire Gang run off to? No one can save us now!",
  ui_story_5010_50101002_13_dialog_content = "Says who?",
  ui_story_5010_50101002_14_dialog_content = "This place... The scent of the deep sea permeates this place.",
  ui_story_5010_50101002_15_dialog_content = "These emergency supplies are for all of you!",
  ui_story_5010_50101002_16_dialog_content = "Rafts, flotation devices, and emergency rations!",
  ui_story_5010_50101002_17_dialog_content = "Listen up!",
  ui_story_5010_50101002_18_dialog_content = "Don't take up all the supplies like hungry, little puppies!",
  ui_story_5010_50101002_19_dialog_content = "It's the Istvan Gang! Istvan Gang has come to our rescue!",
  ui_story_5010_50101002_20_dialog_content = "Great! Now that you're here!",
  ui_story_5010_50101002_21_dialog_content = "Did the Shadowlord order you to defend this place?",
  ui_story_5010_50101002_22_dialog_content = "Tell me, is he safe and sound?",
  ui_story_5010_50101002_23_dialog_content = "Who knows? Can shadows be washed away by the rain, Bethel?",
  ui_story_5010_50101002_24_dialog_content = "We're fixing it from top to bottom, Boss!",
  ui_story_5010_50101002_25_dialog_content = "What's the situation in the other parts of the city?",
  ui_story_5010_50101002_26_dialog_content = "Do we know how many casualties there have been? Where are Solus and the Blue Lions right now? Have any of you seen Maude or Rhein?",
  ui_story_5010_50101002_27_dialog_content = "... Too many questions.",
  ui_story_5010_50101002_28_dialog_content = "Not many casualties yet, no idea where they are, and no, we haven't seen them.",
  ui_story_5010_50101002_29_dialog_content = "Tending to the wounded is tiring enough. No more questions.",
  ui_story_5010_50101002_30_dialog_content = "Although, the guilds that were under attack earlier are under our protection now!",
  ui_story_5010_50101002_31_dialog_content = "The enemy's numbers are starting to dwindle, too...",
  ui_story_5010_50101002_32_dialog_content = "They must have been scared off by our heroic presence. Yeah, that has to be it.",
  ui_story_5010_50101002_33_dialog_content = "Wait... You're telling me there aren't any members of Solus in the city anymore?",
  ui_story_5010_50101002_34_dialog_content = "This doesn't match their previous movements...",
  ui_story_5010_50101002_35_dialog_content = "Is it just me, or is the water level getting higher and higher here?",
  ui_story_5010_50101002_36_dialog_content = "I think so... My tentacles can't catch a break.",
  ui_story_5010_50101002_37_dialog_content = "The water... It's starting to flow in here!!",
  ui_story_5010_50101002_38_dialog_content = "The slums are in low-lying terrain.",
  ui_story_5010_50101002_39_dialog_content = "We're lucky that Istvan Gang is here to help...",
  ui_story_5010_50101002_40_dialog_content = "I can't imagine the trouble these people would be in if it weren't for you guys.",
  ui_story_5010_50101002_41_dialog_content = "Oh, no!",
  ui_story_5010_50101002_42_dialog_content = "If the rain keeps falling like this, the ships and docks on the Gold River will be in danger!",
  ui_story_5010_50101002_43_dialog_content = "The water... the slums... docks and ships... And all this rain...",
  ui_story_5010_50101002_44_dialog_content = "Ah! So that's what going on! I finally understand!",
  ui_story_5010_50101002_45_dialog_content = "<size=45><color=#FFB400>The Dam of Scars!</color></size>",
  ui_story_5010_50101002_46_dialog_content = "That's their target! It's the Dam of Scars!",
  ui_story_5010_50101002_47_dialog_content = "... I get it!",
  ui_story_5010_50101002_48_dialog_content = "If the dam were to break...",
  ui_story_5010_50101002_49_dialog_content = "Umbraton will suffer massive casualties. Not only will the slums be completely wiped out, the city's essential docks will also be heavily damaged.",
  ui_story_5010_50101002_50_dialog_content = "This... this is far worse than anything I had imagined!",
  ui_story_5010_50101002_51_dialog_content = "How can we find out the status of the dam right now?",
  ui_story_5010_50101002_52_dialog_content = "Judging from the amount of water here, it's safe to say it hasn't been critically hit.",
  ui_story_5010_50101002_53_dialog_content = "But we need to get moving, and fast!",
  ui_story_5010_50101101_1_dialog_content = "The dam is just up ahead. Let's scout out the area first.",
  ui_story_5010_50101101_2_dialog_content = "*Gasp* There! It's Maude!",
  ui_story_5010_50101101_3_dialog_content = "... The dam has already been pierced!",
  ui_story_5010_50101101_4_dialog_content = "Looks like it won't hold for much longer...",
  ui_story_5010_50101101_5_dialog_content = "Did you see that? They're using firearms.",
  ui_story_5010_50101101_6_dialog_content = "Hurry, before it's too late!",
  ui_story_5010_50101101_7_dialog_content = "Lord Maude! Lord Rhein!",
  ui_story_5010_50101101_8_dialog_content = "Oh? So they found us, after all.",
  ui_story_5010_50101101_9_dialog_content = "Are you here to witness the fall of the dam as well, Lady Bethel?",
  ui_story_5010_50101101_10_dialog_content = "But not to worry. You will be reunited with your beloved father, Lord Istvan, soon enough.",
  ui_story_5010_50101101_11_dialog_content = "Enough banter. Attack!",
  ui_story_5010_50101101_12_dialog_content = "As if we'd let you get away with this!",
  ui_story_5010_50101101_13_dialog_content = "Not even in your dreams, you traitors!",
  ui_story_5010_50101101_14_dialog_content = "You take care of these insignificant pests.",
  ui_story_5010_50101101_15_dialog_content = "I have something far more important to do. It will take every ounce of my concentration...",
  ui_story_5010_50101101_16_dialog_content = "To prepare this grand surprise for all of Umbraton.",
  ui_story_5010_50101101_17_dialog_content = "I won't let you destroy the dam!",
  ui_story_5010_50101101_18_dialog_content = "Uwaaa!!",
  ui_story_5010_50101101_19_dialog_content = "Must I really deal with these pond scum myself...?",
  ui_story_5010_50101101_20_dialog_content = "I suppose I ought to warm up first...",
  ui_story_5010_50101101_21_dialog_content = "By enjoying the taste of your final, meaningless struggle!",
  ui_story_5010_50101101_22_dialog_content = "You two seem to be in awfully high spirits.",
  ui_story_5010_50101101_23_dialog_content = "<size=45>Y... You...?!</size>",
  ui_story_5010_50101101_24_dialog_content = "<size=45>How... How are you still alive?!</size>",
  ui_story_5010_50101101_25_dialog_content = "You should have been blown to pieces!",
  ui_story_5010_50101101_26_dialog_content = "Maude... I must say, your way of welcoming a new guest is lacking in decorum.",
  ui_story_5010_50101101_27_dialog_content = "Destroying my airship only gave me a few scratches, nothing more...",
  ui_story_5010_50101101_28_dialog_content = "That I stand before you now... Is a testament to the complete and utter failure of your endeavors.",
  ui_story_5010_50101101_29_dialog_content = "Every member of Solus responsible for the strife in the city has been rounded up, as well as their accomplices.",
  ui_story_5010_50101101_30_dialog_content = "Hahaha... I must admit, those transforming monsters were quite challenging, but...",
  ui_story_5010_50101101_31_dialog_content = "Solus is no more, and the Blue Lion Guild will share the same fate.",
  ui_story_5010_50101101_32_dialog_content = "Your assets will be distributed evenly to the rest of Umbraton, as compensation for the trouble you have caused. On behalf of the city's leaders... I would like to offer my heartfelt thanks for your generous donation! Hahahahaha!",
  ui_story_5010_50101101_33_dialog_content = "Do you think you can stop us with your meaningless words?",
  ui_story_5010_50101101_34_dialog_content = "I'm afraid he's telling the truth. Look at the smoke signals rising from the city...",
  ui_story_5010_50101101_35_dialog_content = "It appears we must change strategies, Maude...",
  ui_story_5010_50101101_36_dialog_content = "This is the end of the line for you, Rhein.",
  ui_story_5010_50101101_37_dialog_content = "As for me... I, and I alone, am more than enough!!",
  ui_story_5010_50101101_38_dialog_content = "I will make this place the final resting place for every person here!!!",
  ui_story_5010_50101101_39_dialog_content = "Power... Infinite power... Is mine!!!",
  ui_story_5010_50101101_40_dialog_content = "Here it comes... Maude is going to take those pills!",
  ui_story_5010_50101101_41_dialog_content = "H-He did it... Maude ate them all... He looks completely different from the others who took them!",
  ui_story_5010_50101101_42_dialog_content = "What is this intense pressure?!",
  ui_story_5010_50101101_43_dialog_content = "<anim type=Shake><size=45>Graaaaaaaaagh!!!</size></anim>",
  ui_story_5010_50101101_44_dialog_content = "<anim type=Shake><size=45>Power...</size></anim>",
  ui_story_5010_50101101_45_dialog_content = "Together, everyone! Attack!",
  ui_story_5010_50101101_46_dialog_content = "Father, you are still injured. Let us battle Maude. Please do what you can to protect the dam!",
  ui_story_5010_50101101_47_dialog_content = "On your left, Luke!",
  ui_story_5010_50101101_48_dialog_content = "Look out, he's about to attack!",
  ui_story_5010_50101101_49_dialog_content = "Finally... The time has finally come.",
  ui_story_5010_50101101_50_dialog_content = "Listen to my commands, everyone!!!",
  ui_story_5010_50101201_1_dialog_content = "You're late, PlayerName. The Shadowlord has been waiting for you all this time!",
  ui_story_5010_50101201_2_dialog_content = "Oh! R-Really? I ran over as fast as I could...",
  ui_story_5010_50101201_3_dialog_content = "Though I suppose with meager pickings like this, your tardiness can be excused.",
  ui_story_5010_50101201_4_dialog_content = "Would it kill you to tell the truth, for once? Your tentacles won't fall off if you do, you know?",
  ui_story_5010_50101201_5_dialog_content = "Ah... I knew I wasn't late!",
  ui_story_5010_50101201_6_dialog_content = "Ah...! W-Wait, stay back! I still have other things to take care of!",
  ui_story_5010_50101201_7_dialog_content = "These are the ownership transferal documents for all Caelestite assets, PlayerName. They will require your signature.",
  ui_story_5010_50101201_8_dialog_content = "In addition, as per the Shadowlord's instruction... We would like to offer you the <color=#FFB400>simulation room components</color> from the auction, free of charge, as a token of our gratitude.",
  ui_story_5010_50101201_9_dialog_content = "Luke, of the White Flame Mercenaries, has agreed to deliver the said parts to Eraveil in the near future.",
  ui_story_5010_50101201_10_dialog_content = "Luke! You're here, too!",
  ui_story_5010_50101201_11_dialog_content = "We meet again, you two.",
  ui_story_5010_50101201_12_dialog_content = "My apologies for interrupting your heartfelt reunion.",
  ui_story_5010_50101201_13_dialog_content = "Pittman? Has the trial concluded yet?",
  ui_story_5010_50101201_14_dialog_content = "Not quite... I have come to say farewell. My orders are to escort Rhein back to Lumopolis to continue his trial.",
  ui_story_5010_50101201_15_dialog_content = "It's a miracle he managed to survive in the first place...",
  ui_story_5010_50101201_16_dialog_content = "Wait. Rhein is a citizen of Umbraton. What right do you have to take him back to Lumopolis?",
  ui_story_5010_50101201_17_dialog_content = "I'm sorry... But these orders come from someone high above me.",
  ui_story_5010_50101201_18_dialog_content = "I could not refuse, even if I wanted to do so.",
  ui_story_5010_50101201_19_dialog_content = "But...",
  ui_story_5010_50101201_20_dialog_content = "I might add... That the Shadowlord himself has also approved these orders.",
  ui_story_5010_50101201_21_dialog_content = "Indeed. I wish you the best of luck, Pittman.",
  ui_story_5010_50101201_22_dialog_content = "I thank you once more for your understanding... Shadowlord.",
  ui_story_5010_50101201_23_dialog_content = "PlayerName, Luke, Lady Bethel... Until next we meet.",
  ui_story_5010_50101201_24_dialog_content = "... Father.",
  ui_story_5010_50101201_25_dialog_content = "Shadowlord.",
  ui_story_5010_50101201_26_dialog_content = "Hmm... The mood seems to have improved somewhat.",
  ui_story_5010_50101201_27_dialog_content = "Ah, but of course... The weather has cleared up, after all.",
  ui_story_5010_50101201_28_dialog_content = "Istvan!",
  ui_story_5010_50101201_29_dialog_content = "Hello, PlayerName.",
  ui_story_5010_50101201_30_dialog_content = "Allow me to express my deepest apologies. You were dragged into the troublesome affairs of our city, and in no small way.",
  ui_story_5010_50101201_31_dialog_content = "H-Huh? It was nothing, really... No need to apologize!",
  ui_story_5010_50101201_32_dialog_content = "Father... Can Rhein's fate be so easily...",
  ui_story_5010_50101201_33_dialog_content = "You will understand soon enough, my dear.",
  ui_story_5010_50101201_34_dialog_content = "U-Understand what?",
  ui_story_5010_50101201_35_dialog_content = "I can understand allowing our adversaries to expose their conspiracy themselves, so that we can pick up the pieces afterwards...",
  ui_story_5010_50101201_36_dialog_content = "But shouldn't we be the ones to punish Rhein for his crimes?",
  ui_story_5010_50101201_37_dialog_content = "Huh? You call letting things get out of hand like that a strategy?",
  ui_story_5010_50101201_38_dialog_content = "By letting Rhein show all of his cards, we avoid giving him an opportunity to keep scheming in the shadows, and prevent him and his cohorts from causing more trouble in the future.",
  ui_story_5010_50101201_39_dialog_content = "But if we hadn't gotten the situation under control at the very end... Wouldn't countless people have died because of it?",
  ui_story_5010_50101201_40_dialog_content = "People with pure and naive hearts can't survive here in Umbraton... Especially not in a position of power.",
  ui_story_5010_50101201_41_dialog_content = "Maybe it was a test for Bethel? After all, I'm sure Lord Istvan's given plenty of thought to who will succeed him in the future...",
  ui_story_5010_50101201_42_dialog_content = "Enough about that. In any case, there is a chance that he will be given a lighter sentence in Lumopolis, much less than he deserves.",
  ui_story_5010_50101201_43_dialog_content = "It's not just a possibility. I'd honestly be surprised if they didn't lighten his sentence.",
  ui_story_5010_50101201_44_dialog_content = "Huh?",
  ui_story_5010_50101201_45_dialog_content = "If they wanted to execute or severely punish a criminal, Umbraton is the place to do it. So why would they need to take him back to Lumopolis?",
  ui_story_5010_50101201_46_dialog_content = "No matter how strong Rhein was, if he didn't have some sort of behind-the-scenes help from Lumopolis...",
  ui_story_5010_50101201_47_dialog_content = "Even if he managed to defeat us, he wouldn't have been able to act as Shadowlord for very long.",
  ui_story_5010_50101201_48_dialog_content = "If those hidden players don't want Rhein dead yet, then I'm sure they won't let him be executed.",
  ui_story_5010_50101201_49_dialog_content = "Am I right, Your Honor?",
  ui_story_5010_50101201_50_dialog_content = "I understand your words, but this is a topic I would much rather avoid discussing.",
  ui_story_5010_50101201_51_dialog_content = "Lady Bethel, I can assure you that Lord Istvan's decision is one that he has put much thought into. Please do not be so upset by it.",
  ui_story_5010_50101201_52_dialog_content = "He's probably the most rational person, to have been in this position for so long.",
  ui_story_5010_50101201_53_dialog_content = "I can understand it, but I still refuse to accept it.",
  ui_story_5010_50101201_54_dialog_content = "Whether it's Lumopolis or Umbraton... their schemes deepens every day.",
  ui_story_5010_50101201_55_dialog_content = "One more thing, PlayerName. My investigation into the enhancers is still ongoing. I am certain I will need your help in the future.",
  ui_story_5010_50101201_56_dialog_content = "Isn't that obvious? People are cooperating with Eclipse, and...",
  ui_story_5010_50101201_57_dialog_content = "I must ask that you refrain from making any unsubstantiated claims before we obtain proper evidence. Finding the truth will require no small amount of patience.",
  ui_story_5010_50101201_58_dialog_content = "*Sigh* Fine.",
  ui_story_5010_50101201_59_dialog_content = "I will continue to track down Rhein's remaining allies in Umbraton. We will catch every last one of those scoundrels.",
  ui_story_5010_50101201_60_dialog_content = "The cost of the rebellion was too grave. We can't let it happen again.",
  ui_story_5010_50101201_61_dialog_content = "Bethel, Rhein was not the first person to challenge Istvan, nor will he be the last.",
  ui_story_5010_50101201_62_dialog_content = "Judging from this outcome, Istvan is strong enough to handle the situation, so everyone should continue to maintain order here.",
  ui_story_5010_50101201_63_dialog_content = "All mercenary squads, gangs, and guilds...",
  ui_story_5010_50101201_64_dialog_content = "Ah, guilds... By the way, Luke, what is the situation with the Lin family?",
  ui_story_5010_50101201_65_dialog_content = "I've already inquired. The core members of the Lin family are excavating a mysterious relic, and they won't be back anytime soon.",
  ui_story_5010_50101201_66_dialog_content = "I see. I'll have to thank the Lin family when I get the chance.",
  ui_story_5010_50101201_67_dialog_content = "We'll let you know as soon as we know anything.",
  ui_story_5010_50101201_68_dialog_content = "Well, it's time to say goodbye to you all.",
  ui_story_5010_50101201_69_dialog_content = "Dear Naroxel:",
  ui_story_5010_50101201_70_dialog_content = "\"So, that sums up our trip to Umbraton... Although I have some regrets...\"",
  ui_story_5010_50101201_71_dialog_content = "\"I'm still glad we got the simulation room components...\"",
  ui_story_5010_50101201_72_dialog_content = "\"Their specific use is still unknown. I have contacted several scientific and technological experts...\"",
  ui_story_5010_50101201_73_dialog_content = "\"Thank you again, Naroxel. And may nature watch over you.\"",
  ui_story_5010_50101201_74_dialog_content = "\"From your friend, PlayerName.\""
}
